/* Swatch-sized anchor the bloom overlays so it opens where the swatch was */
.bcp__slot {
   position: relative;
   width: calc(50px * var(--bcp-scale));
   height: calc(50px * var(--bcp-scale));
   flex-shrink: 0;
}

/* --- Closed swatch --- */
.bcp__swatch {
   width: calc(50px * var(--bcp-scale));
   height: calc(50px * var(--bcp-scale));
   border-radius: 50%;
   border: none;
   padding: 0;
   cursor: pointer;
   flex-shrink: 0;
   box-shadow: 0 2px 8px var(--bcp-swatch-shadow);
   outline: calc(1.5px * var(--bcp-scale)) solid var(--bcp-swatch-ring);
   transition:
      transform var(--bcp-dur-press) var(--bcp-ease-press),
      background-color 0.25s ease-out;
   animation: bcp-swatch-in 0.18s ease-out;
}

.bcp__swatch--pressing {
   transform: scale(0.85);
}

.bcp__swatch:disabled {
   cursor: not-allowed;
   opacity: 0.55;
}

/* --- Hex input ---
   The wrap is what's actually positioned/z-indexed (outside the swatch's
   box, so it never shifts what the bloom considers "center" — the bloom
   always opens from the swatch). It shrink-wraps to the input's real
   rendered width (no JS measurement) since only `left` is set, not `right`.
   Stays mounted (not hidden) while open. z-index sits below the arc(0),
   bloom(1), and petals(2) so the bloom opens over it, not under it. */
.bcp__input-wrap {
   position: absolute;
   z-index: -1;
   top: 50%;
   left: 0;
   transform: translateY(-50%);
   padding-left: calc(50px * var(--bcp-scale) + 14px * var(--bcp-scale));
}

.bcp__input {
   border: 1px solid var(--bcp-input-border);
   background: var(--bcp-input-bg);
   border-radius: calc(16px * var(--bcp-scale));
   padding: calc(10px * var(--bcp-scale)) calc(14px * var(--bcp-scale));
   font-family: var(--bcp-font-input, ui-monospace, "SF Mono", "Cascadia Code", monospace);
   font-size: calc(21px * var(--bcp-scale));
   font-weight: 400;
   color: var(--bcp-input-color);
   transition: color 0.15s ease-out;
   animation: bcp-swatch-in 0.18s ease-out;
}

.bcp__input:focus {
   color: var(--bcp-input-color-focus);
}

.bcp__input:disabled {
   cursor: not-allowed;
   opacity: 0.55;
}

/* grouped: swatch + input share one pill background instead of two boxes.
   The wrap's padding-left already reaches back under the swatch, so the
   shared background just needs its own bg/border/height — the swatch
   itself (a later, higher z-indexed sibling) paints over the left end. */
.bcp[data-input-variant="grouped"] .bcp__input-wrap {
   display: flex;
   align-items: center;
   left: calc(-12px * var(--bcp-scale));
   height: calc(70px * var(--bcp-scale));
   padding-left: calc(50px * var(--bcp-scale) + 16px * var(--bcp-scale));
   padding-right: calc(10px * var(--bcp-scale));
   background: var(--bcp-input-bg);
   border: 1px solid var(--bcp-input-border);
   border-radius: calc(22px * var(--bcp-scale));
}

.bcp[data-input-variant="grouped"] .bcp__input {
   background: transparent;
   border-color: transparent;
   padding: calc(16px * var(--bcp-scale)) calc(6px * var(--bcp-scale));
   font-size: calc(29px * var(--bcp-scale));
}

/* The input's own box sits smaller/offset inside the visible pill in grouped
   mode, so a focus ring on the input itself doesn't trace the pill's actual
   shape. Ring the wrap instead (its real border-radius) via :focus-within. */
.bcp[data-input-variant="grouped"] .bcp__input:focus-visible {
   outline: none;
}

.bcp[data-input-variant="grouped"] .bcp__input-wrap:focus-within {
   outline: 2px solid var(--bcp-color-focus);
   outline-offset: 2px;
}

/* bouncy: the swatch springs back in (scale overshoot) when the bloom
   closes, reusing the press spring so it matches the swatch's own tap feel */
.bcp[data-motion="bouncy"] .bcp__swatch {
   animation: bcp-swatch-in-bouncy var(--bcp-dur-press) var(--bcp-ease-press);
}

@keyframes bcp-swatch-in-bouncy {
   from {
      opacity: 0;
      transform: scale(0.8);
   }
   to {
      opacity: 1;
      transform: scale(1);
   }
}

@keyframes bcp-swatch-in {
   from {
      opacity: 0;
   }
   to {
      opacity: 1;
   }
}

/* --- Dahlia bloom --- */
.bcp__bloom {
   position: absolute;
   z-index: 1;
   top: 50%;
   left: 50%;
   width: calc(280px * var(--bcp-scale));
   height: calc(280px * var(--bcp-scale));
   margin: calc(-140px * var(--bcp-scale)) 0 0 calc(-140px * var(--bcp-scale));
   border-radius: 50%;
   box-sizing: border-box;
   box-shadow: 0 8px 28px var(--bcp-bloom-shadow);
   /* opens from swatch size (50/280) at the same center */
   animation:
      bcp-bloom-in var(--bcp-dur-bloom) var(--bcp-ease-bloom) backwards,
      bcp-unblur-3 0.26s ease-out backwards;
   transition: background-color 0.25s ease-out;
}

@keyframes bcp-bloom-in {
   from {
      transform: scale(0.1786);
   }
   to {
      transform: scale(1);
   }
}

@keyframes bcp-unblur-3 {
   from {
      filter: blur(3px);
   }
   to {
      filter: blur(0px);
   }
}

.bcp__bloom--closing {
   /* keyframe (not transition) so the exit reliably replaces the entrance animation */
   animation: bcp-bloom-out 0.22s cubic-bezier(0.42, 0, 1, 1) forwards;
}

@keyframes bcp-bloom-out {
   from {
      transform: scale(1);
      opacity: 1;
      filter: blur(0px);
   }
   to {
      transform: scale(0.1786);
      opacity: 0;
      filter: blur(3px);
   }
}

.bcp__dish {
   position: absolute;
   inset: calc(20px * var(--bcp-scale));
   border-radius: 50%;
   background: var(--bcp-dish-bg);
   overflow: hidden;
   animation: bcp-dish-in var(--bcp-dur-dish) var(--bcp-ease-dish) 0.05s backwards;
}

@keyframes bcp-dish-in {
   from {
      transform: scale(0.4);
      opacity: 0;
      filter: blur(8px);
   }
   to {
      transform: scale(1);
      opacity: 1;
      filter: blur(0px);
   }
}

/* --- Brightness arc --- */
.bcp__arc {
   position: absolute;
   top: 50%;
   left: 50%;
   margin-top: calc(-180px * var(--bcp-scale));
   margin-left: calc(-180px * var(--bcp-scale));
   transform-origin: center;
   z-index: 0;
   pointer-events: none;
   overflow: visible;
   animation: bcp-arc-in var(--bcp-dur-arc) var(--bcp-ease-arc) 0.28s backwards;
}

@keyframes bcp-arc-in {
   from {
      opacity: 0;
      transform: scale(0.3);
      filter: blur(8px);
   }
   to {
      opacity: 1;
      transform: scale(1);
      filter: blur(0px);
   }
}

.bcp__arc--closing {
   animation: bcp-arc-out 0.16s cubic-bezier(0.42, 0, 1, 1) forwards;
}

@keyframes bcp-arc-out {
   from {
      opacity: 1;
      transform: scale(1);
      filter: blur(0px);
   }
   to {
      opacity: 0;
      transform: scale(0.3);
      filter: blur(8px);
   }
}

.bcp__knob {
   pointer-events: auto;
}

.bcp__knob-halo {
   r: 14.5px;
   filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.25));
   transition: r var(--bcp-dur-knob) var(--bcp-ease-knob);
}

.bcp__knob-core {
   r: 11.5px;
   transition: r var(--bcp-dur-knob) var(--bcp-ease-knob);
}

.bcp--dragging .bcp__knob-halo {
   r: 16.5px;
}

.bcp--dragging .bcp__knob-core {
   r: 13.5px;
}

/* --- Petals --- */
.bcp__petal {
   position: absolute;
   z-index: 2;
   border: none;
   border-radius: 50%;
   padding: 0;
   cursor: pointer;
   box-shadow: 0 1px 4px var(--bcp-petal-shadow);
   /* spiral entrance from the center, staggered per petal */
   animation: bcp-petal-in var(--bcp-dur-petal) var(--bcp-ease-petal) var(--bcp-petal-delay)
      backwards;
   transition: transform var(--bcp-dur-petal-hover) var(--bcp-ease-petal-hover);
}

@keyframes bcp-petal-in {
   from {
      transform: translate(var(--bcp-from-x), var(--bcp-from-y)) scale(1.5);
      opacity: 0;
      filter: blur(12px);
   }
   to {
      transform: translate(0, 0) scale(1);
      opacity: 1;
      filter: blur(0px);
   }
}

.bcp__petal--hovered {
   transform: scale(1.18);
}

.bcp__petal:active {
   transform: scale(0.95);
   transition-duration: 0.1s;
}

/* close phase 2: all rings converge back to the center */
.bcp__petal--home {
   animation: bcp-petal-out 0.34s ease-in-out forwards;
   transition: none;
   pointer-events: none;
}

@keyframes bcp-petal-out {
   from {
      transform: translate(0, 0) scale(1);
      opacity: 1;
      filter: blur(0px);
   }
   to {
      transform: translate(var(--bcp-from-x), var(--bcp-from-y)) scale(1);
      opacity: 0;
      filter: blur(3px);
   }
}

@media (prefers-reduced-motion: reduce) {
   .bcp,
   .bcp * {
      animation-duration: 0.01ms !important;
      animation-delay: 0ms !important;
      transition-duration: 0.01ms !important;
      transition-delay: 0ms !important;
   }
}

/* motion="none" — a quick uniform fade, not an instant snap. Overrides every
   spring/bounce curve and stagger delay with one plain ease-out, independent
   of the visitor's OS motion setting. */
.bcp[data-motion="none"],
.bcp[data-motion="none"] * {
   animation-duration: 160ms !important;
   animation-timing-function: ease-out !important;
   animation-delay: 0ms !important;
   transition-duration: 160ms !important;
   transition-timing-function: ease-out !important;
   transition-delay: 0ms !important;
}
